for r in recipes:
    if r['number'] in (1,2,6,7):
        r['labels'].insert(2, {1:'先把图中位置写成不等式',2:'读出 A、a、B、C、b、D 的次序',6:'到原点距离 3，有两个 A',7:'先把三点次序写成两个不等式'}[r['number']])
        r['states'].insert(2, r['states'][0].copy())
    if r['number']==18 and r['partId']=='2':
        r['labels']=['x 必须与 1、2 不同','用最左与最右计算跨度','先排除重复元素 1 与 2','跨度为 3，把端点差写出来','左右两侧分别求解','代回 −1 和 4，确认全部解']
        r['states']=[{'x':0},{'x':3},{'x':1},{'x':-1},{'x':4},{'x':-1}]
    if r['number']==14:
        r['labels'][2]='上下两个界相遇：|b−3|=3'
        r['labels'][3]='c=1，b 有 0 和 6 两个分支'
out=[]
for recipe in recipes:
    n=recipe['number']; raw=json.loads((ROOT/f'data/runtime/paper-motion-audit/q{n}.json').read_text())
    q,l=raw['question'],raw['lesson']; p=approved_part(next(p for p in l['parts'] if p['partId']==recipe['partId']))
    count=len(p['steps'])+3
    if len(recipe['labels'])!=count or len(recipe['states'])!=count:
        raise ValueError((n,recipe['partId'],count,len(recipe['labels']),len(recipe['states'])))
    key=f'paper-q{n}-{recipe["partId"].replace(".","-")}-v1'
    target=dict(questionId=q['id'],questionRevision=q['revision'],lessonVersion=l['lessonVersion'],partId=p['partId'],lessonHash=canonical_hash(p))
    recipe.update(key=key,target=target,stageCount=count)
    out.append(recipe)
    concepts=[dict(id=f'k{i}',label=f'知识 {i+1}',explanation=text) for i,text in enumerate(p['prerequisites'])]
    if not concepts: concepts=[dict(id='k0',label=recipe['title'],explanation=recipe['action'])]
    stages=[]
    for i,label in enumerate(recipe['labels']):
        explanation=p['goal'] if i==0 else p['method'] if i==1 else p['steps'][i-2]['reason'] if i<count-1 else p['summary']
        stages.append(dict(stageIndex=i,template=key,title=label,conceptIds=[c['id'] for c in concepts],focus=recipe['action'],explanation=explanation))
    pack=dict(schemaVersion=1,title=recipe['title'],subject='math',author='Codex',target=target,concepts=concepts,stages=stages)
    (ROOT/f'resources/codex/paper/q{n}-{p["partId"].replace(".","-")}.json').write_text(json.dumps(pack,ensure_ascii=False,indent=2)+'\n')
(ROOT/'web/src/paper-resources/catalog.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
sources=[]
for n in range(1,28):
    raw=json.loads((ROOT/f'data/runtime/paper-motion-audit/q{n}.json').read_text())
    q,l=raw['question'],raw['lesson']
    sources.append({'question':{key:q[key] for key in ('id','revision','number','state','missingFields','parts')},'lesson': None if l is None else {**{key:l[key] for key in ('questionId','questionRevision','lessonVersion','status','checks','coveredPartIds')},'parts':[approved_part(p) for p in l['parts']]}})
(ROOT/'resources/codex/paper/lesson-sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n')
print(f'Authored {len(out)} resources; Q26 keeps its existing voiced composition; Q11 remains blocked.')
